intentos.respuesta_cruda:
{
  "sql": "SELECT t1.product_category_name_english, ROUND(100.0 * SUM(CASE WHEN t2.payment_installments > 1 THEN 1 ELSE 0 END) / COUNT(DISTINCT t2.order_id), 2) AS pct_pagos_plazos FROM product_category_translation AS t1 LEFT JOIN order_items AS t2 ON t1.product_category_name = t2.product_category_name INNER JOIN order_payments AS t3 ON t2.order_id = t3.order_id WHERE t3.payment_type != 'not_defined' GROUP BY t1.product_category_name_english HAVING COUNT(DISTINCT t2.order_id) >= 100 ORDER BY pct_pagos_plazos DESC LIMIT 1"
}
